void themgiua(node **head, int x, int k){
    int n = len(*head);
    if(k < 1 || k > n + 1) return;      // vi tri khong hop le
    node *newNode = makeNode(x);
    if(k == 1){                         // khong co node k-1
        newNode->next = *head;
        if(*head) (*head)->prev = newNode;
        *head = newNode; return;
    }
    node *tmp = *head;
    for(int i = 1; i <= k - 1; i++) tmp = tmp->next;  // toi node k
    newNode->next = tmp; tmp->prev->next = newNode;
    newNode->prev = tmp->prev; tmp->prev = newNode;
}
